const nodeCrypto = require('crypto');
const rules = $input.all().map(i => i.json).filter(r => r && r.pattern);
const form = $('Receive Report').first().json;
const policy = $('Set Channel Policy').first().json;
const text = String(form.report_text || '');
const lower = text.toLowerCase();
const hard = [];
const soft = [];
let rulePoints = 0;
for (const r of rules) {
  let matched = '';
  if (r.match_type === 'regex') {
    try { const m = text.match(new RegExp(r.pattern, 'i')); if (m) { matched = m[0]; } } catch (e) { continue; }
  } else if (lower.includes(String(r.pattern).toLowerCase())) { matched = String(r.pattern); }
  if (!matched) continue;
  const entry = { pattern: matched, category: String(r.category || ''), points: Number(r.points) || 0, note: String(r.note || '') };
  if (r.severity === 'hard') { hard.push(entry); } else { soft.push(entry); }
  rulePoints += entry.points;
}
const caseId = 'WB-' + nodeCrypto.randomBytes(4).toString('hex').toUpperCase();
const tokenPlain = nodeCrypto.randomBytes(16).toString('hex');
const tokenHash = nodeCrypto.createHash('sha256').update(tokenPlain).digest('hex');
const contact = String(form.contact_optional || '').trim();
return [{ json: {
  case_id: caseId,
  token_plain: tokenPlain,
  token_hash: tokenHash,
  category_reported: String(form.category || ''),
  report_text: text,
  contact_optional: contact,
  contact_left: contact ? 'yes' : 'no',
  rules_loaded: rules.length,
  hard_hits: hard,
  soft_hits: soft,
  rule_points: rulePoints,
  ack_days: Number(policy.ack_days),
  feedback_days: Number(policy.feedback_days),
  urgent_at: Number(policy.urgent_at),
  model_max_points: Number(policy.model_max_points)
} }];

