const scan = $('Scan Report And Create Case').first().json;
const first = $input.first();
const raw = first ? first.json : {};
const src = raw && typeof raw.output === 'object' && raw.output !== null ? raw.output : raw;
let modelNote = 'Groq summarised the report.';
let conf = Number(src ? src.confidence : NaN);
if (!Number.isFinite(conf)) { conf = 0; modelNote = 'The model did not return a readable answer; triage rests on the deterministic rules alone.'; }
if (conf > 0 && conf <= 1) { conf = Math.round(conf * 100); }
conf = Math.max(0, Math.min(100, Math.round(conf)));
let hint = Number(src ? src.urgency_hint : NaN);
if (!Number.isFinite(hint)) { hint = 0; }
if (hint > 0 && hint <= 1) { hint = Math.round(hint * 100); }
hint = Math.max(0, Math.min(100, Math.round(hint)));
const cap = Number.isFinite(Number(scan.model_max_points)) ? Number(scan.model_max_points) : 30;
const modelPoints = Math.min(cap, Math.round(hint * (conf / 100) * (cap / 100)));
const score = Math.min(100, (Number(scan.rule_points) || 0) + modelPoints);
const hard = Array.isArray(scan.hard_hits) ? scan.hard_hits : [];
let urgency = 'STANDARD';
let refusal = '';
if (Number(scan.rules_loaded) === 0) {
  urgency = 'MANUAL_REVIEW';
  refusal = 'The urgency rules table is empty, so nothing was actually screened. This channel refuses to auto-triage without its reference rules; a human must review this case first.';
} else if (hard.length > 0 || score >= (Number(scan.urgent_at) || 60)) {
  urgency = 'URGENT';
}
const now = Date.now();
const ackDue = new Date(now + (Number(scan.ack_days) || 7) * 86400000).toISOString().slice(0, 10);
const feedbackDue = new Date(now + (Number(scan.feedback_days) || 90) * 86400000).toISOString().slice(0, 10);
const summary = String((src && src.summary) || '').slice(0, 500) || 'No model summary available.';
const categoryModel = String((src && src.category) || 'unclassified');
return [{ json: {
  case_id: scan.case_id,
  token_plain: scan.token_plain,
  token_hash: scan.token_hash,
  received_at: new Date(now).toISOString(),
  category_reported: scan.category_reported,
  category_model: categoryModel,
  urgency: urgency,
  risk_score: score,
  status: urgency === 'MANUAL_REVIEW' ? 'received - awaiting manual triage' : 'received',
  ack_due: ackDue,
  feedback_due: feedbackDue,
  contact_optional: String(scan.contact_optional || ''),
  contact_left: scan.contact_left,
  summary: summary,
  report_text: scan.report_text,
  triage_note: modelNote + (refusal ? ' ' + refusal : '')
} }];

