const nodeCrypto = require('crypto');
const form = $('Check Case Status').first().json;
const caseId = String(form.case_id || '').trim().toUpperCase();
const code = String(form.access_code || '').trim();
const rows = $input.all().map(i => i.json).filter(r => r && r.case_id);
const codeHash = nodeCrypto.createHash('sha256').update(code).digest('hex');
const row = rows.find(r => String(r.case_id).toUpperCase() === caseId);
const verified = Boolean(row && row.token_hash === codeHash);
return [{ json: {
  verified: verified ? 'yes' : 'no',
  case_id: caseId,
  status: verified ? String(row.status) : '',
  urgency: verified ? String(row.urgency) : '',
  received_at: verified ? String(row.received_at).slice(0, 10) : '',
  ack_due: verified ? String(row.ack_due) : '',
  feedback_due: verified ? String(row.feedback_due) : ''
} }];

